effect.shader:
void main() {
    int n = clamp(int(samples), 4, 32);
    vec2 p = acScreenNorm - center;
    p.x *= acAspect;
    float d = length(p);
    float peso = smoothstep(focus, focus + 0.3, d);
    if (peso <= 0.0 || abs(depth) < 1e-4) { fragColor = texture(inputImg, acScreenNorm); return; }

    vec4 soma = vec4(0.0);
    for (int i = 0; i <= 32; i++) {
        if (i > n) break;
        float t = float(i) / float(n) - 0.5;
        float escala = 1.0 + depth * peso * t;
        vec2 q = p / escala;
        q.x /= acAspect;
        soma += texture(inputImg, q + center);
    }
    fragColor = soma / float(n + 1);
}
